Ext.define('BNK.view.Budget.bgx.com.BgxComScrp51MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.BgxComScrp51MViewController',

    config: {
        viewId: 'BgxComScrp51M'
    },

    fnConfirm: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            v = me.getView(),
            record = vm.get('record');

        if (record.existCanApvl == 'Y') {
            // 승인취소 내역여부
            Ext.Msg.show({
                buttons :  {
                    yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                },
                title : '알림',
                message : '[ '+record.mcNm+' ] 에 대해 같은 승인번호에 대한 취소/정상 승인내역 있습니다.<br>',
                alwaysOnTop : true,
                fn : function(btn) {
                    me.onBtnSelect();
                }
            });
        } else {
            v.fireEvent('onConfirm', vm.get('record'));
            v.close();
        }
    },

    /* 닫기 */
    onBtnClose: function(button, e, eOpts) {
        this.getView().fireEvent('onClose');
        this.getView().close();
    },

    /* 조회 */
    onBtnSelect: function(button, e, eOpts) {
        var scrpCntView = this.getReferences().scrp_container.items.items[0],
            scrpCntCtrl = scrpCntView.controller;

        scrpCntCtrl.onSelect();
    },

    /* 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            scrpCnt = refs.scrp_container,
            data = component.config.data;

        if (!data) {
            this.onBtnClose();
        }

        // 01 : 법인카드, 02 : 현금영수증
        var aplKndcd = data.aplKndcd,
            cntId = (aplKndcd == Constants.aplKndcd.CARD) ? 'BgxComScrp01M' : (aplKndcd == Constants.aplKndcd.CSH_RCT) ? 'BgxComScrp02M' : '';
        if (!cntId) {
            this.onBtnClose();
        }

        scrpCnt.add(Ext.create(cntId, {data : data}));
    }

});